/**
 * Dhātu pack: verified conjugations (laṭ, laṅ, lṛṭ, loṭ, vidhiliṅ), kṛdantas and common prefixed
 * verbs. See ./README.md for conventions and the verification method; the data is generated by
 * tools/content/verbal/gen-dhatu.ts and must not be edited by hand.
 */
import type { Forms, Lakara, Level, PackMeta, Pada, Purusha, Vacana } from '../types';
import { DHATU_DATA, PREFIXED_DATA } from './data';
import { parseTable, type DhatuEntry, type PrefixedVerb, type RawDhatu } from './types';

export type { DhatuEntry, PrefixedVerb } from './types';

export const LAKARAS: readonly Lakara[] = ['lat', 'lan', 'lrt', 'lot', 'vidhilin'];

const SOURCE = 'ashtadhyayi.com dhātu tables (generated by vidyut-prakriya), cross-checked cell by cell';

function expand(raw: RawDhatu): DhatuEntry {
  const forms: DhatuEntry['forms'] = {};
  for (const lakara of LAKARAS) {
    const byPada = raw.forms[lakara];
    if (!byPada) continue;
    const out: Partial<Record<Pada, Forms[][]>> = {};
    if (byPada.P !== undefined) out.P = parseTable(byPada.P);
    if (byPada.A !== undefined) out.A = parseTable(byPada.A);
    forms[lakara] = out;
  }
  const krdanta: DhatuEntry['krdanta'] = {};
  for (const [k, v] of Object.entries(raw.krdanta) as [keyof DhatuEntry['krdanta'], string][]) krdanta[k] = v.split('/');
  const entry: DhatuEntry = {
    id: raw.id,
    dhatu: raw.dhatu,
    gana: raw.gana,
    pada: raw.pada,
    en: raw.en,
    artha: raw.artha,
    upadesha: raw.upadesha,
    dhatupatha: raw.dhatupatha,
    level: raw.level,
    forms,
    krdanta,
    evidence: raw.evidence,
    provenance: { source: `${SOURCE}; dhātupāṭha ${raw.dhatupatha} ${raw.upadesha} ${raw.artha}`, verifiedBy: raw.verifiedBy },
  };
  if (raw.note !== undefined) entry.note = raw.note;
  if (raw.lyap !== undefined) entry.lyap = raw.lyap;
  return entry;
}

/** All dhātus, ordered by gaṇa and, within a gaṇa, roughly by frequency of use. */
/**
 * Corrections from the independent audit of 11 Nov 2026 (docs/audit/SANSKRIT_AUDIT_A.md): kṛdanta display
 * forms that are doubtful are withheld (a missing form is fine, a wrong one is not). Fold into
 * tools/content/verbal when regenerating: लोक् / मार्ग् (gaṇa 10) showed the non-ṇic लोकित्वा, लोकितुम्,
 * मार्गित्वा, मार्गितुम्; विद् (gaṇa 6, "find") showed विदितः / विदित्वा, which belong to विद् "know".
 */
export const WITHHELD_KRDANTA: Readonly<Record<string, readonly (keyof DhatuEntry['krdanta'])[]>> = {
  'lok-10u': ['ktva', 'tumun'],
  'marg-10u': ['ktva', 'tumun'],
  'vid-6u': ['kta', 'ktva', 'ktavatu'],
};

function applyAudit(d: DhatuEntry): DhatuEntry {
  const drop = WITHHELD_KRDANTA[d.id];
  if (!drop) return d;
  const krdanta = { ...d.krdanta };
  for (const k of drop) delete krdanta[k];
  return { ...d, krdanta };
}

export const DHATUS: readonly DhatuEntry[] = DHATU_DATA.map(expand).map(applyAudit);

const BY_ID = new Map(DHATUS.map((d) => [d.id, d]));

export function dhatu(id: string): DhatuEntry | undefined {
  return BY_ID.get(id);
}

/** Accepted forms of one cell, display form first; [] when the cell (or lakāra / pada) is not available. */
export function conj(d: DhatuEntry, lakara: Lakara, pada: Pada, purusha: Purusha, vacana: Vacana): Forms {
  return d.forms[lakara]?.[pada]?.[purusha - 1]?.[vacana - 1] ?? [];
}

/** Padas in which the dhātu has forms (laṭ decides; a pada that only appears in another lakāra is appended). */
export function padasOf(d: DhatuEntry): Pada[] {
  const out: Pada[] = [];
  for (const lakara of LAKARAS) {
    for (const pada of ['P', 'A'] as const) {
      if (d.forms[lakara]?.[pada] && !out.includes(pada)) out.push(pada);
    }
  }
  return out;
}

/** Dhātus at or below the given level (cumulative). */
export function dhatusForLevel(level: Level): DhatuEntry[] {
  return DHATUS.filter((d) => d.level <= level);
}

/** Common prefixed verbs (upasarga / gati + dhātu) with their laṭ 3sg. */
export const PREFIXED: readonly PrefixedVerb[] = PREFIXED_DATA.map((p) => ({
  id: p.id,
  upasarga: p.upasarga,
  base: p.base,
  lat3s: p.lat3s,
  en: p.en,
  level: p.level,
  provenance: { source: `upasarga + verified laṭ 3sg of ${p.base}, joined by tools/content/verbal/prefixed-build.ts and attested`, verifiedBy: p.verifiedBy },
}));

export function prefixedForLevel(level: Level): PrefixedVerb[] {
  return PREFIXED.filter((p) => p.level <= level);
}

